/* ==========================================================================
   BoloUp Live Official Website - Sitewide External Stylesheet
   Teal (#0D94B6) to Emerald Mint (#13C091) Full-Screen Gradient Theme
   WordPress Elementor Compatible - Ultra-Vibrant Full-Screen Color
   ========================================================================== */

/* 1. Custom Google Font via @import */
@import url('https://fonts.googleapis.com/css2?family=Plus+Jakarta+Sans:wght@400;500;600;700;800;900&display=swap');

/* 2. Global CSS Variables & Design Tokens */
:root {
  /* Brand Gradient Palette sampled directly from user swatch */
  --color-teal: #0D94B6;
  --color-turquoise: #00A7B3;
  --color-aqua: #00B3A6;
  --color-mint: #00BE98;
  --color-emerald: #13C091;

  /* Vibrant Full-Screen Teal-to-Emerald Base Colors (No dark/black!) */
  --color-bg-base: #083c47;
  --color-bg-deep: #062f38;
  --color-header-glass: rgba(6, 45, 54, 0.85);

  /* Primary Gradients */
  --grad-primary: linear-gradient(135deg, #0D94B6 0%, #00B3A6 50%, #13C091 100%);
  --grad-primary-hover: linear-gradient(135deg, #0BB2DA 0%, #00CBB9 50%, #17E2A9 100%);
  --grad-cta-banner: linear-gradient(135deg, rgba(13, 148, 182, 0.85) 0%, rgba(19, 192, 145, 0.75) 100%);
  --grad-card: rgba(6, 42, 51, 0.55);
  --grad-card-hover: rgba(8, 55, 66, 0.75);

  /* Text & Surfaces */
  --color-white: #FFFFFF;
  --text-title: #FFFFFF;
  --text-body: rgba(255, 255, 255, 0.92);
  --text-muted: rgba(255, 255, 255, 0.7);

  /* Borders & Glows */
  --border-card: rgba(19, 192, 145, 0.3);
  --border-card-hover: rgba(19, 192, 145, 0.75);
  --glow-accent: 0 0 30px rgba(19, 192, 145, 0.45);
  --glow-button: 0 8px 25px rgba(0, 179, 166, 0.5);
  --glow-button-hover: 0 12px 35px rgba(19, 192, 145, 0.7);

  /* Layout & Sizing */
  --font-main: 'Plus Jakarta Sans', -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
  --max-width: 1200px;
  --header-height: 80px;
  --radius-sm: 8px;
  --radius-md: 16px;
  --radius-lg: 24px;
  --radius-xl: 32px;
  --radius-pill: 9999px;
  --transition: all 0.3s cubic-bezier(0.16, 1, 0.3, 1);
}

/* 3. Base Reset */
*,
*::before,
*::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

html {
  scroll-behavior: smooth;
  font-size: 16px;
  background-color: var(--color-bg-base);
}

body {
  font-family: var(--font-main);
  background-color: #0D94B6 !important;
  color: var(--text-body);
  line-height: 1.65;
  overflow-x: hidden;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
  background-image: linear-gradient(135deg, #0D94B6 0%, #00B3A6 50%, #13C091 100%) !important;
  background-attachment: fixed !important;
  background-repeat: no-repeat !important;
  background-size: cover !important;
  min-height: 100vh;
}

/* WordPress Elementor Full-Bleed Compatibility */
#page,
.site,
.site-content,
.elementor,
.elementor-section-wrap,
.elementor-section,
.e-con,
.e-con-boxed,
.e-con-full,
.elementor-widget-wrap,
.elementor-widget-html {
  background-color: transparent !important;
  width: 100% !important;
  max-width: 100% !important;
}

a {
  color: inherit;
  text-decoration: none;
}

img {
  max-width: 100%;
  height: auto;
  display: block;
}

button {
  font-family: inherit;
  border: none;
  background: none;
  cursor: pointer;
}

/* 4. Layout Container */
.container {
  width: 100%;
  max-width: var(--max-width);
  margin-left: auto;
  margin-right: auto;
  padding-left: 24px;
  padding-right: 24px;
}

/* 5. Typography Utility Classes */
.text-gradient,
.highlight-violet,
.highlight-pink {
  color: var(--color-white) !important;
  -webkit-text-fill-color: var(--color-white) !important;
  text-shadow: 0 0 20px rgba(255, 255, 255, 0.6), 0 2px 10px rgba(0, 0, 0, 0.35) !important;
  display: inline;
}

/* 6. Section Architecture (Full-Screen Vivid Teal-to-Green) */
.section,
.section-alt,
.section-white,
.section-dark {
  padding: 100px 0;
  position: relative;
  background-color: transparent !important;
  color: var(--text-body);
}

.section-title-wrap {
  text-align: center;
  max-width: 760px;
  margin: 0 auto 56px;
}

.section-badge {
  display: inline-flex;
  align-items: center;
  padding: 6px 18px;
  border-radius: var(--radius-pill);
  font-size: 0.85rem;
  font-weight: 700;
  letter-spacing: 0.05em;
  text-transform: uppercase;
  margin-bottom: 16px;
  background: rgba(19, 192, 145, 0.18);
  color: var(--color-emerald);
  border: 1px solid rgba(19, 192, 145, 0.45);
  box-shadow: 0 0 15px rgba(0, 179, 166, 0.25);
  backdrop-filter: blur(8px);
}

.section-title {
  color: var(--text-title);
  font-size: clamp(2rem, 3.8vw, 2.75rem);
  font-weight: 800;
  line-height: 1.2;
  letter-spacing: -0.02em;
  text-shadow: 0 2px 10px rgba(0, 0, 0, 0.3);
}

/* 7. Buttons System */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  padding: 14px 30px;
  border-radius: var(--radius-pill);
  font-size: 1rem;
  font-weight: 700;
  text-align: center;
  text-decoration: none;
  transition: var(--transition);
  cursor: pointer;
  white-space: nowrap;
}

.btn-primary {
  background: var(--grad-primary);
  color: var(--color-white) !important;
  box-shadow: var(--glow-button);
  border: 1px solid rgba(255, 255, 255, 0.3);
}

.btn-primary:hover {
  background: var(--grad-primary-hover);
  transform: translateY(-2px);
  box-shadow: var(--glow-button-hover);
}

.btn-secondary {
  background: rgba(6, 42, 51, 0.6);
  color: var(--color-white) !important;
  border: 1.5px solid var(--color-emerald);
  box-shadow: 0 4px 15px rgba(0, 0, 0, 0.2);
  backdrop-filter: blur(8px);
}

.btn-secondary:hover {
  background: var(--grad-primary);
  color: var(--color-white) !important;
  transform: translateY(-2px);
  box-shadow: var(--glow-button);
}

.btn-outline {
  background: rgba(6, 42, 51, 0.35);
  color: var(--color-white) !important;
  border: 1.5px solid rgba(19, 192, 145, 0.6);
  backdrop-filter: blur(8px);
}

.btn-outline:hover {
  border-color: var(--color-emerald);
  background: rgba(19, 192, 145, 0.25);
  transform: translateY(-2px);
  box-shadow: var(--glow-button);
}

.btn-sm {
  padding: 9px 20px;
  font-size: 0.88rem;
}

.btn-lg {
  padding: 16px 38px;
  font-size: 1.1rem;
}

/* ==========================================================================
   8. Header Component (header.html) - Full Width & Teal-Green Glass
   ========================================================================== */
.header {
  position: sticky;
  top: 0;
  left: 0;
  width: 100%;
  z-index: 1000;
  background: var(--color-header-glass) !important;
  backdrop-filter: blur(16px);
  -webkit-backdrop-filter: blur(16px);
  border-bottom: 1px solid rgba(19, 192, 145, 0.3);
  transition: background 0.3s ease, box-shadow 0.3s ease;
}

.header.header-scrolled {
  background: rgba(6, 40, 48, 0.96) !important;
  border-bottom-color: rgba(19, 192, 145, 0.5);
  box-shadow: 0 10px 30px rgba(0, 0, 0, 0.4);
}

.header-container {
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: var(--header-height);
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 0 24px;
}

.header .brand-logo,
.brand-logo {
  display: flex !important;
  align-items: center !important;
  height: 38px !important;
  max-height: 38px !important;
  text-decoration: none !important;
  z-index: 1001;
}

.header .brand-logo-icon,
.header .brand-logo img,
.brand-logo-icon,
.brand-logo img {
  height: 30px !important;
  max-height: 30px !important;
  width: auto !important;
  max-width: 120px !important;
  object-fit: contain !important;
  display: block !important;
  border: none !important;
  box-shadow: none !important;
  transition: transform 0.25s ease;
}

.brand-logo:hover .brand-logo-icon,
.brand-logo:hover img {
  transform: scale(1.04);
}

.nav-menu {
  display: flex;
  align-items: center;
  gap: 28px;
}

.nav-link {
  color: var(--text-body);
  font-size: 0.95rem;
  font-weight: 500;
  transition: var(--transition);
  position: relative;
  padding: 6px 0;
}

.nav-link:hover {
  color: var(--color-white);
}

.nav-link.active {
  color: var(--color-white);
  font-weight: 700;
}

.nav-link.active::after {
  content: '';
  position: absolute;
  bottom: 0;
  left: 0;
  width: 100%;
  height: 2px;
  background: var(--grad-primary);
  box-shadow: 0 0 10px var(--color-emerald);
  border-radius: var(--radius-pill);
}

.header-actions {
  display: flex;
  align-items: center;
  gap: 12px;
}

.mobile-nav-actions {
  display: none;
}

.menu-toggle {
  display: none;
  font-size: 1.5rem;
  color: var(--color-white);
  padding: 6px;
  line-height: 1;
}

/* ==========================================================================
   9. Hero Section (#hero) - Full Screen & Vibrant Teal-Emerald
   ========================================================================== */
.hero-section {
  position: relative;
  width: 100%;
  min-height: calc(100vh - var(--header-height));
  display: flex;
  align-items: center;
  padding: 40px 0 80px;
  overflow: hidden;
}

.hero-grid {
  display: grid;
  grid-template-columns: 1.15fr 0.85fr;
  align-items: center;
  gap: 48px;
  width: 100%;
}

.hero-content {
  position: relative;
  z-index: 2;
}

.hero-title {
  color: var(--text-title);
  font-size: clamp(2.6rem, 5vw, 4.2rem);
  font-weight: 800;
  line-height: 1.14;
  letter-spacing: -0.025em;
  margin-bottom: 24px;
  text-shadow: 0 2px 12px rgba(0, 0, 0, 0.4);
}

.hero-desc {
  color: var(--text-body);
  font-size: clamp(1.05rem, 1.25vw, 1.2rem);
  line-height: 1.75;
  margin-bottom: 36px;
  max-width: 580px;
  text-shadow: 0 1px 6px rgba(0, 0, 0, 0.3);
}

.hero-actions {
  display: flex;
  align-items: center;
  gap: 16px;
  flex-wrap: wrap;
}

/* Hero Visual & Ambient Floating Decorations */
.hero-visual {
  position: relative;
  display: flex;
  justify-content: center;
  align-items: center;
  z-index: 1;
}

.hero-glow-backdrop {
  position: absolute;
  width: 500px;
  height: 500px;
  border-radius: 50%;
  background: radial-gradient(circle, rgba(19, 192, 145, 0.5) 0%, rgba(13, 148, 182, 0.35) 45%, transparent 70%);
  filter: blur(45px);
  pointer-events: none;
  z-index: 0;
  animation: pulseGlow 6s ease-in-out infinite alternate;
}

@keyframes pulseGlow {
  0% { transform: scale(0.92); opacity: 0.7; }
  100% { transform: scale(1.1); opacity: 1; }
}

.hero-visual-frame {
  position: relative;
  z-index: 1;
  width: 100%;
  max-width: 500px;
}

.hero-img-wrap {
  width: 100%;
  display: flex;
  justify-content: center;
}

.hero-img {
  width: 100%;
  max-height: 640px;
  object-fit: contain;
  filter: drop-shadow(0 20px 40px rgba(0, 0, 0, 0.5));
}

/* Floating virtual gifts, diamonds, hearts */
.hero-float-element {
  position: absolute;
  z-index: 3;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 50%;
  pointer-events: none;
  box-shadow: 0 8px 24px rgba(0, 0, 0, 0.4);
  backdrop-filter: blur(12px);
  background: rgba(6, 42, 51, 0.7);
  border: 1.5px solid rgba(19, 192, 145, 0.5);
}

.float-diamond {
  top: 10%;
  left: -10px;
  width: 56px;
  height: 56px;
  box-shadow: 0 0 25px rgba(13, 148, 182, 0.6);
  animation: floatSlow 5s ease-in-out infinite;
}

.float-heart {
  bottom: 22%;
  left: 5px;
  width: 50px;
  height: 50px;
  box-shadow: 0 0 20px rgba(19, 192, 145, 0.5);
  animation: floatHeart 4.2s ease-in-out infinite 0.8s;
}

.float-gift {
  top: 18%;
  right: -5px;
  width: 54px;
  height: 54px;
  box-shadow: 0 0 25px rgba(0, 179, 166, 0.6);
  animation: floatGift 4.8s ease-in-out infinite 1.4s;
}

.float-star-1 {
  bottom: 12%;
  right: 25px;
  width: 42px;
  height: 42px;
  animation: floatSlow 6s ease-in-out infinite 2s;
}

.float-star-2 {
  top: 4%;
  right: 80px;
  width: 36px;
  height: 36px;
  animation: floatHeart 3.6s ease-in-out infinite 0.5s;
}

@keyframes floatSlow {
  0%, 100% { transform: translateY(0px) rotate(0deg); }
  50% { transform: translateY(-14px) rotate(4deg); }
}

@keyframes floatHeart {
  0%, 100% { transform: translateY(0px) scale(1); }
  50% { transform: translateY(-12px) scale(1.08); }
}

@keyframes floatGift {
  0%, 100% { transform: translateY(0px) rotate(0deg); }
  50% { transform: translateY(-16px) rotate(-5deg); }
}

/* ==========================================================================
   10. What Is BoloUp Section (#what-is-boloup)
   ========================================================================== */
.about-split-grid {
  display: grid;
  grid-template-columns: 1.05fr 0.95fr;
  align-items: center;
  gap: 56px;
}

.about-content-col {
  display: flex;
  flex-direction: column;
  gap: 20px;
}

.about-text-paragraphs {
  display: flex;
  flex-direction: column;
  gap: 16px;
}

.what-desc {
  font-size: 1.05rem;
  line-height: 1.8;
  color: var(--text-body);
}

.what-cta-wrap {
  margin-top: 12px;
}

/* Ecosystem Interactive Feature Box */
.about-visual-col {
  display: flex;
  justify-content: center;
}

.about-interactive-card {
  width: 100%;
  max-width: 500px;
  background: var(--grad-card);
  border-radius: var(--radius-lg);
  padding: 32px;
  box-shadow: 0 20px 50px rgba(0, 0, 0, 0.35);
  border: 1px solid var(--border-card);
  backdrop-filter: blur(16px);
  -webkit-backdrop-filter: blur(16px);
}

.eco-badge-wrap {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  margin-bottom: 24px;
}

.eco-chip {
  background: rgba(19, 192, 145, 0.15);
  color: var(--color-white);
  border: 1px solid rgba(19, 192, 145, 0.35);
  padding: 6px 14px;
  border-radius: var(--radius-pill);
  font-size: 0.82rem;
  font-weight: 600;
  transition: var(--transition);
}

.eco-chip:hover {
  background: var(--grad-primary);
  transform: translateY(-1px);
}

.eco-card-main {
  background: rgba(6, 32, 39, 0.5);
  border-radius: var(--radius-md);
  padding: 24px;
  border: 1px solid rgba(19, 192, 145, 0.25);
}

.eco-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 14px;
  margin-bottom: 20px;
}

.eco-icon {
  font-size: 1.8rem;
  width: 48px;
  height: 48px;
  border-radius: 12px;
  background: rgba(19, 192, 145, 0.22);
  border: 1px solid rgba(19, 192, 145, 0.45);
  display: flex;
  align-items: center;
  justify-content: center;
}

.eco-title {
  color: var(--text-title);
  font-size: 1.15rem;
  font-weight: 700;
}

.eco-sub {
  color: var(--text-muted);
  font-size: 0.85rem;
}

/* Sound Bars animation */
.sound-bars {
  display: flex;
  align-items: flex-end;
  gap: 3px;
  height: 24px;
}

.sound-bar {
  width: 4px;
  background: var(--grad-primary);
  box-shadow: 0 0 8px var(--color-emerald);
  border-radius: 2px;
  animation: equalizer 1.2s ease-in-out infinite alternate;
}

.sound-bar:nth-child(1) { height: 40%; animation-delay: 0.1s; }
.sound-bar:nth-child(2) { height: 80%; animation-delay: 0.3s; }
.sound-bar:nth-child(3) { height: 100%; animation-delay: 0s; }
.sound-bar:nth-child(4) { height: 60%; animation-delay: 0.4s; }
.sound-bar:nth-child(5) { height: 35%; animation-delay: 0.2s; }

@keyframes equalizer {
  0% { transform: scaleY(0.3); }
  100% { transform: scaleY(1); }
}

.eco-chat-preview {
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.chat-bubble {
  background: rgba(6, 28, 34, 0.65);
  border: 1px solid rgba(19, 192, 145, 0.25);
  border-radius: 12px;
  padding: 10px 14px;
  font-size: 0.9rem;
}

.chat-user {
  font-weight: 700;
  color: var(--color-emerald);
  margin-right: 6px;
}

.chat-msg {
  color: var(--text-body);
}

/* ==========================================================================
   11. Benefits Section (#benefits)
   ========================================================================== */
.benefits-bento {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 28px;
}

.bento-card {
  position: relative;
  background: var(--grad-card);
  border: 1px solid var(--border-card);
  border-radius: var(--radius-lg);
  padding: 38px 30px;
  transition: var(--transition);
  display: flex;
  flex-direction: column;
  overflow: hidden;
  backdrop-filter: blur(16px);
  -webkit-backdrop-filter: blur(16px);
}

.bento-card:hover {
  background: var(--grad-card-hover);
  border-color: var(--border-card-hover);
  transform: translateY(-6px);
  box-shadow: 0 20px 45px rgba(0, 0, 0, 0.35), var(--glow-accent);
}

.bento-number {
  position: absolute;
  top: 24px;
  right: 28px;
  font-size: 2.5rem;
  font-weight: 900;
  line-height: 1;
  color: rgba(19, 192, 145, 0.3);
  pointer-events: none;
  transition: var(--transition);
}

.bento-card:hover .bento-number {
  color: var(--color-emerald);
  text-shadow: 0 0 20px rgba(19, 192, 145, 0.7);
}

.bento-icon-box {
  width: 58px;
  height: 58px;
  border-radius: 16px;
  background: rgba(19, 192, 145, 0.2);
  border: 1px solid rgba(19, 192, 145, 0.45);
  color: var(--color-white);
  display: flex;
  align-items: center;
  justify-content: center;
  margin-bottom: 24px;
  box-shadow: 0 4px 15px rgba(0, 179, 166, 0.3);
  transition: var(--transition);
}

.bento-card:hover .bento-icon-box {
  background: var(--grad-primary);
  box-shadow: var(--glow-button);
}

.bento-title {
  color: var(--text-title);
  font-size: 1.35rem;
  font-weight: 700;
  line-height: 1.3;
  margin-bottom: 14px;
}

.bento-desc {
  color: var(--text-body);
  font-size: 0.98rem;
  line-height: 1.7;
}

/* Featured Center Card */
.bento-card-accent {
  border-color: rgba(19, 192, 145, 0.6);
  background: rgba(8, 55, 66, 0.7);
  box-shadow: 0 10px 30px rgba(0, 179, 166, 0.25);
}

/* ==========================================================================
   12. Earnings Section (#earnings)
   ========================================================================== */
.earnings-grid-luxury {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 32px;
}

.earning-card-luxury {
  background: var(--grad-card);
  border: 1px solid var(--border-card);
  border-radius: var(--radius-lg);
  padding: 40px;
  backdrop-filter: blur(16px);
  -webkit-backdrop-filter: blur(16px);
  transition: var(--transition);
  display: flex;
  flex-direction: column;
}

.earning-card-luxury:hover {
  background: var(--grad-card-hover);
  border-color: var(--border-card-hover);
  transform: translateY(-5px);
  box-shadow: 0 20px 45px rgba(0, 0, 0, 0.35), var(--glow-accent);
}

.earning-top-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 24px;
}

.earning-icon-pill {
  font-size: 2rem;
  width: 56px;
  height: 56px;
  border-radius: 16px;
  background: rgba(19, 192, 145, 0.2);
  border: 1px solid rgba(19, 192, 145, 0.45);
  display: flex;
  align-items: center;
  justify-content: center;
  box-shadow: 0 4px 18px rgba(0, 179, 166, 0.35);
}

.earning-badge-pill {
  background: rgba(19, 192, 145, 0.18);
  color: var(--color-emerald);
  border: 1px solid rgba(19, 192, 145, 0.4);
  padding: 6px 16px;
  border-radius: var(--radius-pill);
  font-size: 0.82rem;
  font-weight: 600;
}

.earning-card-title {
  color: var(--text-title);
  font-size: 1.45rem;
  font-weight: 700;
  line-height: 1.3;
  margin-bottom: 16px;
}

.earning-card-desc {
  color: var(--text-body);
  font-size: 1.02rem;
  line-height: 1.75;
  margin-bottom: 28px;
  flex-grow: 1;
}

.earning-visual-strip {
  display: flex;
  flex-wrap: wrap;
  gap: 10px;
}

.gift-chip {
  background: rgba(19, 192, 145, 0.15);
  border: 1px solid rgba(19, 192, 145, 0.35);
  color: var(--color-white);
  padding: 7px 16px;
  border-radius: var(--radius-pill);
  font-size: 0.85rem;
  font-weight: 600;
  transition: var(--transition);
}

.gift-chip:hover {
  background: var(--grad-primary);
  transform: translateY(-1px);
}

/* ==========================================================================
   13. Registration Section (#registration)
   ========================================================================== */
.registration-timeline-wrap {
  max-width: 900px;
  margin: 0 auto;
}

.reg-steps-flow {
  display: flex;
  flex-direction: column;
  gap: 20px;
}

.reg-step-card {
  background: var(--grad-card);
  border: 1px solid var(--border-card);
  border-radius: var(--radius-md);
  padding: 28px 32px;
  box-shadow: 0 10px 30px rgba(0, 0, 0, 0.25);
  transition: var(--transition);
  backdrop-filter: blur(16px);
  -webkit-backdrop-filter: blur(16px);
}

.reg-step-card:hover {
  border-color: var(--border-card-hover);
  background: var(--grad-card-hover);
  transform: translateY(-3px);
  box-shadow: 0 16px 36px rgba(0, 0, 0, 0.35), var(--glow-accent);
}

.reg-step-header {
  display: flex;
  align-items: center;
  gap: 16px;
  margin-bottom: 14px;
}

.reg-step-num {
  width: 44px;
  height: 44px;
  border-radius: 50%;
  background: var(--grad-primary);
  color: var(--color-white);
  font-size: 1.1rem;
  font-weight: 800;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  box-shadow: var(--glow-button);
  flex-shrink: 0;
}

.reg-step-icon {
  width: 40px;
  height: 40px;
  border-radius: 10px;
  background: rgba(19, 192, 145, 0.2);
  color: var(--color-white);
  display: flex;
  align-items: center;
  justify-content: center;
}

.reg-step-title {
  color: var(--text-title);
  font-size: 1.25rem;
  font-weight: 700;
  margin-bottom: 10px;
}

.reg-step-desc {
  color: var(--text-body);
  font-size: 1rem;
  line-height: 1.7;
}

/* Highlighted Step 3 - Agency ID Box */
.reg-step-highlight {
  border: 1.5px solid var(--color-emerald);
  background: rgba(8, 55, 66, 0.7);
  box-shadow: 0 12px 35px rgba(0, 179, 166, 0.3);
}

.agency-id-callout {
  margin-top: 22px;
  background: rgba(4, 25, 32, 0.85);
  border-radius: var(--radius-md);
  padding: 24px;
  border: 1.5px solid var(--color-emerald);
  box-shadow: 0 0 25px rgba(0, 179, 166, 0.35);
}

.agency-id-label {
  color: var(--text-muted);
  font-size: 0.82rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.06em;
  margin-bottom: 12px;
}

.agency-id-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  flex-wrap: wrap;
}

.agency-id-code {
  font-size: 2.2rem;
  font-weight: 800;
  letter-spacing: 3px;
  color: var(--color-white);
  text-shadow: 0 0 20px var(--color-emerald);
}

.btn-copy-id {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  background: var(--grad-primary);
  color: var(--color-white);
  padding: 11px 24px;
  border-radius: var(--radius-pill);
  font-size: 0.95rem;
  font-weight: 700;
  box-shadow: var(--glow-button);
  transition: var(--transition);
}

.btn-copy-id:hover {
  background: var(--grad-primary-hover);
  transform: translateY(-2px);
  box-shadow: var(--glow-button-hover);
}

.btn-copy-id.copied {
  background: #10b981;
  box-shadow: 0 8px 20px rgba(16, 185, 129, 0.5);
}

.copy-feedback-toast {
  display: none;
  margin-top: 12px;
  font-size: 0.88rem;
  color: #34d399;
  font-weight: 600;
  animation: fadeIn 0.3s ease;
}

.copy-feedback-toast.show {
  display: block;
}

@keyframes fadeIn {
  from { opacity: 0; transform: translateY(-4px); }
  to { opacity: 1; transform: translateY(0); }
}

/* ==========================================================================
   14. FAQ Section (#faqs)
   ========================================================================== */
.faq-accordion {
  max-width: 820px;
  margin: 0 auto;
  display: flex;
  flex-direction: column;
  gap: 16px;
}

.faq-item {
  background: var(--grad-card);
  border: 1px solid var(--border-card);
  border-radius: var(--radius-md);
  overflow: hidden;
  transition: var(--transition);
  backdrop-filter: blur(16px);
  -webkit-backdrop-filter: blur(16px);
}

.faq-item:hover {
  border-color: var(--border-card-hover);
  background: var(--grad-card-hover);
}

.faq-item.active {
  background: rgba(8, 55, 66, 0.75);
  border-color: var(--color-emerald);
  box-shadow: 0 10px 30px rgba(0, 179, 166, 0.3);
}

.faq-question {
  width: 100%;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  padding: 24px 28px;
  text-align: left;
}

.faq-q-text {
  display: flex;
  align-items: center;
  gap: 14px;
  color: var(--text-title);
  font-size: 1.15rem;
  font-weight: 700;
  line-height: 1.35;
}

.faq-q-num {
  background: rgba(19, 192, 145, 0.25);
  color: var(--color-emerald);
  font-size: 0.85rem;
  font-weight: 800;
  padding: 4px 10px;
  border-radius: 8px;
  flex-shrink: 0;
}

.faq-icon {
  width: 32px;
  height: 32px;
  border-radius: 50%;
  background: rgba(19, 192, 145, 0.2);
  color: var(--color-white);
  font-size: 1.25rem;
  font-weight: 700;
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  transition: var(--transition);
}

.faq-item.active .faq-icon {
  transform: rotate(45deg);
  background: var(--color-emerald);
  box-shadow: 0 0 12px var(--color-emerald);
}

.faq-answer {
  max-height: 0;
  overflow: hidden;
  transition: max-height 0.35s cubic-bezier(0.16, 1, 0.3, 1);
}

.faq-answer-inner {
  padding: 0 28px 24px 28px;
}

.faq-answer-inner p {
  color: var(--text-body);
  font-size: 1.02rem;
  line-height: 1.75;
}

/* ==========================================================================
   15. Final CTA Section (#cta)
   ========================================================================== */
.cta-section-wrapper {
  padding: 80px 0 110px;
}

.cta-banner-epic {
  position: relative;
  background: var(--grad-cta-banner);
  border-radius: var(--radius-xl);
  padding: 70px 40px;
  text-align: center;
  overflow: hidden;
  border: 1.5px solid rgba(255, 255, 255, 0.35);
  box-shadow: 0 25px 60px rgba(0, 0, 0, 0.4), var(--glow-accent);
}

.cta-glow-element {
  position: absolute;
  width: 340px;
  height: 340px;
  border-radius: 50%;
  filter: blur(60px);
  pointer-events: none;
}

.cta-glow-element.top-left {
  top: -120px;
  left: -120px;
  background: rgba(13, 148, 182, 0.6);
}

.cta-glow-element.bottom-right {
  bottom: -120px;
  right: -120px;
  background: rgba(19, 192, 145, 0.6);
}

.cta-content-inner {
  position: relative;
  z-index: 2;
  max-width: 640px;
  margin: 0 auto;
}

.cta-title {
  color: var(--text-title);
  font-size: clamp(2rem, 4vw, 3rem);
  font-weight: 800;
  line-height: 1.2;
  letter-spacing: -0.02em;
  margin-bottom: 32px;
  text-shadow: 0 2px 10px rgba(0, 0, 0, 0.4);
}

.cta-actions {
  display: flex;
  justify-content: center;
}

/* ==========================================================================
   16. Footer Component (footer.html) - Matches Header Glass Theme
   ========================================================================== */
.footer,
footer.footer,
.site-footer,
.elementor-location-footer {
  width: 100% !important;
  max-width: 100% !important;
  margin-left: 0 !important;
  margin-right: 0 !important;
  box-sizing: border-box !important;
  position: relative;
  background-color: #062d36 !important;
  background: rgba(6, 45, 54, 0.95) !important;
  backdrop-filter: blur(16px);
  -webkit-backdrop-filter: blur(16px);
  color: var(--text-body);
  border-top: 1px solid rgba(19, 192, 145, 0.35);
  box-shadow: 0 -10px 30px rgba(0, 0, 0, 0.25);
  padding: 80px 0 35px;
}

.footer .container {
  width: 100% !important;
  max-width: var(--max-width);
  margin-left: auto !important;
  margin-right: auto !important;
  padding-left: 24px !important;
  padding-right: 24px !important;
  box-sizing: border-box !important;
}

.footer-grid {
  display: grid;
  grid-template-columns: 1.5fr 1fr 1fr 1.2fr;
  gap: 48px;
  margin-bottom: 56px;
}

.footer-brand {
  display: flex;
  flex-direction: column;
  gap: 18px;
}

.footer-desc {
  color: var(--text-muted);
  font-size: 0.95rem;
  line-height: 1.7;
  max-width: 340px;
}

.footer-col h3 {
  color: var(--text-title);
  font-size: 1.1rem;
  font-weight: 700;
  margin-bottom: 20px;
  letter-spacing: -0.01em;
}

.footer-links {
  list-style: none;
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.footer-links a {
  color: var(--text-body);
  font-size: 0.95rem;
  transition: var(--transition);
}

.footer-links a:hover {
  color: var(--color-emerald);
  transform: translateX(3px);
  display: inline-block;
}

.footer-bottom {
  display: flex;
  align-items: center;
  justify-content: space-between;
  border-top: 1px solid rgba(19, 192, 145, 0.25);
  padding-top: 28px;
  color: var(--text-muted);
  font-size: 0.9rem;
  flex-wrap: wrap;
  gap: 16px;
}

.footer .brand-logo-icon,
.footer .brand-logo img {
  height: 36px !important;
  max-height: 36px !important;
  width: auto !important;
  max-width: 140px !important;
}

/* ==========================================================================
   17. Responsive Design Breakpoints (Mobile-First)
   ========================================================================== */

/* Tablet & Smaller Desktop (max-width: 1024px) */
@media (max-width: 1024px) {
  .hero-section {
    min-height: auto;
    padding: 40px 0 60px;
  }

  .hero-grid {
    grid-template-columns: 1fr;
    text-align: center;
    gap: 40px;
  }

  .hero-desc {
    margin-left: auto;
    margin-right: auto;
  }

  .hero-actions {
    justify-content: center;
  }

  .about-split-grid {
    grid-template-columns: 1fr;
    gap: 40px;
  }

  .benefits-bento {
    grid-template-columns: 1fr;
    gap: 20px;
  }

  .earnings-grid-luxury {
    grid-template-columns: 1fr;
    gap: 24px;
  }

  .footer-grid {
    grid-template-columns: 1fr 1fr;
    gap: 36px;
  }
}

/* Mobile Devices (max-width: 768px) */
@media (max-width: 768px) {
  .section {
    padding: 64px 0;
  }

  .header .brand-logo,
  .brand-logo {
    height: 32px !important;
    max-height: 32px !important;
  }

  .header .brand-logo-icon,
  .header .brand-logo img,
  .brand-logo-icon,
  .brand-logo img {
    height: 26px !important;
    max-height: 26px !important;
  }

  .header-actions .btn {
    display: none;
  }

  .menu-toggle {
    display: block;
  }

  .nav-menu {
    position: fixed;
    top: var(--header-height);
    left: 0;
    width: 100%;
    height: calc(100vh - var(--header-height));
    background: rgba(6, 40, 48, 0.98);
    backdrop-filter: blur(20px);
    -webkit-backdrop-filter: blur(20px);
    flex-direction: column;
    padding: 32px 24px;
    gap: 20px;
    transform: translateX(-100%);
    transition: transform 0.35s cubic-bezier(0.16, 1, 0.3, 1);
    overflow-y: auto;
  }

  .nav-menu.active {
    transform: translateX(0);
  }

  .nav-link {
    font-size: 1.15rem;
    padding: 10px 0;
    width: 100%;
    border-bottom: 1px solid rgba(19, 192, 145, 0.2);
  }

  .mobile-nav-actions {
    display: flex;
    flex-direction: column;
    gap: 12px;
    width: 100%;
    margin-top: 16px;
  }

  .mobile-nav-actions .btn {
    width: 100%;
  }

  .hero-title {
    font-size: 2.2rem;
  }

  .hero-visual-frame {
    max-width: 360px;
  }

  .hero-glow-backdrop {
    width: 300px;
    height: 300px;
  }

  .float-diamond {
    width: 44px;
    height: 44px;
  }

  .float-heart {
    width: 40px;
    height: 40px;
  }

  .float-gift {
    width: 44px;
    height: 44px;
  }

  .reg-step-card {
    padding: 22px 20px;
  }

  .agency-id-callout {
    padding: 18px;
  }

  .agency-id-code {
    font-size: 1.6rem;
  }

  .cta-banner-epic {
    padding: 48px 24px;
    border-radius: var(--radius-lg);
  }

  .footer-grid {
    grid-template-columns: 1fr;
    gap: 32px;
  }

  .footer-bottom {
    flex-direction: column;
    text-align: center;
  }
}
